:root {
  --color-bg: #020617;
  --color-surface: #0f172a;
  --color-border: #1e293b;
  --color-primary: #10b981;
  --color-danger: #f43f5e;
  --font-main: 'Inter', system-ui, sans-serif;
}
body { background-color: var(--color-bg); color: #f8fafc; font-family: var(--font-main); margin: 0; padding: 0; }
.nav-menu-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 12px; font-weight: 600; }
.nav-item { display: flex; align-items: center; gap: 10px; padding: 10px 14px; border-radius: 8px; background: #1e293b; color: #38bdf8; text-decoration: none; transition: all 0.2s; }
.nav-item:hover { background: #0284c7; color: #ffffff; transform: translateY(-1px); }

.admin-toolbar { display: flex; justify-content: space-between; align-items: center; padding: 16px; background: #0f172a; border-bottom: 1px solid #1e293b; }
.btn-group { display: flex; gap: 10px; flex-wrap: wrap; }
.btn-action { padding: 8px 16px; border-radius: 6px; font-weight: 600; cursor: pointer; border: none; display: inline-flex; align-items: center; gap: 8px; transition: 0.2s; }
.btn-create { background: #10b981; color: #fff; }
.btn-edit { background: #0284c7; color: #fff; }
.btn-delete { background: #f43f5e; color: #fff; }
.btn-import { background: #8b5cf6; color: #fff; }
.btn-export { background: #64748b; color: #fff; }

.dashboard-filter-bar { display: flex; align-items: center; justify-content: space-between; background: #0f172a; padding: 12px 20px; border-radius: 12px; margin-bottom: 20px; }
.year-selector { background: #1e293b; color: #10b981; border: 1px solid #334155; padding: 8px 14px; border-radius: 6px; font-size: 14px; font-weight: 600; }
.kpi-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 16px; }
.kpi-card { background: #0f172a; border: 1px solid #1e293b; border-radius: 12px; padding: 20px; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.3); }

.audit-cards-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap: 20px; margin-top: 24px; }
.claim-card { background: #0f172a; border-left: 4px solid #10b981; border-radius: 8px; padding: 18px; border-top: 1px solid #1e293b; border-right: 1px solid #1e293b; border-bottom: 1px solid #1e293b; }
.claim-card.critical { border-left-color: #f43f5e; }
.claim-card.warning { border-left-color: #f59e0b; }

.kanban-board { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; overflow-x: auto; padding-bottom: 16px; }
.kanban-col { background: #0f172a; border-radius: 12px; padding: 16px; border: 1px solid #1e293b; min-height: 500px; }
.kanban-card { background: #1e293b; border-radius: 8px; padding: 14px; margin-bottom: 12px; border: 1px solid #334155; cursor: grab; }

.model-switcher { display: flex; gap: 12px; margin-bottom: 20px; }
.model-badge { padding: 10px 16px; border-radius: 8px; background: #0f172a; border: 1px solid #1e293b; cursor: pointer; }
.model-badge.active { border-color: #10b981; background: #022c22; color: #34d399; }

.team-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 16px; }
.member-card { background: #0f172a; border: 1px solid #1e293b; border-radius: 12px; padding: 18px; display: flex; align-items: center; gap: 16px; }
.role-badge { font-size: 11px; text-transform: uppercase; padding: 4px 8px; border-radius: 4px; background: #0284c7; color: #fff; font-weight: 700; }

document.addEventListener('DOMContentLoaded', () => {
  console.log('🚀 GreenHumble v1.1 Admin JS initialisé.');
  const token = localStorage.getItem('greenhumble_jwt_token');
  if (!token && !window.location.pathname.includes('login')) {
    console.info('Authentification requise pour accès aux endpoints REST.');
  }
});

function filterDashboardByYear(year) {
  console.log('🔄 Filtrage du cockpit pour l\'année :', year);
  fetch(`/api/admin/config?action=stats&year=${year}`)
    .then(r => r.json())
    .then(data => {
       document.getElementById('total-audits-count').innerText = data.totalAudits || 0;
    }).catch(err => console.warn('Erreur filtre année :', err));
}

async function submitAuditForm(event) {
  event.preventDefault();
  const urlInput = document.getElementById('audit-url').value;
  const token = localStorage.getItem('greenhumble_jwt_token');
  const res = await fetch('/api/audit', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${token}`
    },
    body: JSON.stringify({ url: urlInput, scanVars: { strictnessLevel: 'strict' } })
  });
  const data = await res.json();
  renderAuditCards(data);
}

async function updateProspectStatus(id, newStatus) {
  await fetch('/api/prospec', {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ id, status: newStatus })
  });
}

function handleRuleAction(action, ruleId) {
  console.log(`Action console IA [${action}] sur règle [${ruleId}]`);
  if (action === 'delete') {
    fetch(`/api/admin/config?id=${ruleId}`, { method: 'DELETE' });
  }
}

function loadTeamMembers() {
  fetch('/api/admin/teams').then(r => r.json()).then(members => console.log('Équipe chargée', members));
}

async function triggerManualBackup() {
  const res = await fetch('/api/admin/backup/create', { method: 'POST' });
  const data = await res.json();
  alert('Sauvegarde créée : ' + data.data.backup_id);
}
